    var pts=[]; for(var i=0;i<=400;i++) pts.push([plotX(pointAtFrac(i/400)[0]),plotY(pointAtFrac(i/400)[1])]);
    staticG.polyline(pts.map(function(p){return p[0]+','+p[1];}).join(' ')).fill('none').stroke({color:BLUE,width:cw,linecap:'round',linejoin:'round'});
    // endpoint labels
    txt(staticG,0.5,0.95,'P = P₀',Math.max(13,20*s),'middle');
    txt(staticG,6.3,9.75,'Q = Pₙ',Math.max(13,20*s),'middle');
    // zoom arrow (cream band) from loop bottom-right to inset
    var T=[4.35,5.55], H=[8.0,3.35], Cc=[6.6,4.6];
    function qz(t){var v=1-t;return [v*v*T[0]+2*v*t*Cc[0]+t*t*H[0], v*v*T[1]+2*v*t*Cc[1]+t*t*H[1]];}
    var band=[]; for(var i=0;i<=40;i++){var p=qz(i/40);band.push([plotX(p[0]),plotY(p[1])]);}
    var bstr=band.map(function(p){return p[0]+','+p[1];}).join(' ');
    staticG.polyline(bstr).fill('none').stroke({color:CREAMEDGE,width:Math.max(10,30*s),linecap:'round'});
    staticG.polyline(bstr).fill('none').stroke({color:CREAM,width:Math.max(7,24*s),linecap:'round'});
    var tang=Math.atan2(plotY(H[1])-plotY(Cc[1]),plotX(H[0])-plotX(Cc[0]));
    arrowHead(staticG,plotX(H[0]),plotY(H[1]),tang,Math.max(14,34*s),CREAM);
    staticG.line(plotX(H[0]),plotY(H[1]),plotX(H[0])-Math.cos(tang)*Math.max(14,34*s),plotY(H[1])-Math.sin(tang)*Math.max(14,34*s)).stroke({color:CREAMEDGE,width:2});
    // inset base arc
    var ip=[]; for(var i=0;i<=60;i++){var p=insetPoint(i/60);ip.push([plotX(p[0]),plotY(p[1])]);}
    staticG.polyline(ip.map(function(p){return p[0]+','+p[1];}).join(' ')).fill('none').stroke({color:BLUE,width:cw,linecap:'round'});
    staticG.circle(Math.max(6,9*s)*2).center(plotX(IA[0]),plotY(IA[1])).fill(BLUE);
    staticG.circle(Math.max(6,9*s)*2).center(plotX(IB[0]),plotY(IB[1])).fill(BLUE);
    txt(staticG,IA[0],IA[1]-0.55,'Pₖ₋₁',Math.max(12,18*s),'middle');
    txt(staticG,IB[0]+0.25,IB[1]+0.1,'Pₖ',Math.max(12,18*s),'start');
    // inset Δs_k double arrow with ticks
    var ay=IB[1]+0.95;
    staticG.line(plotX(IA[0]),plotY(IA[1]+0.35),plotX(IA[0]),plotY(ay+0.25)).stroke({color:'#222',width:1.4});
    staticG.line(plotX(IB[0]),plotY(IB[1]+0.35),plotX(IB[0]),plotY(ay+0.25)).stroke({color:'#222',width:1.4});
    darrow(staticG,plotX(IA[0]),plotY(ay),plotX(IB[0]),plotY(ay),'#222',1.6);
    txt(staticG,(IA[0]+IB[0])/2,ay+0.45,'Δsₖ',Math.max(12,18*s),'middle');
    // formula box
    var fx0=plotX(2.1),fy0=plotY(1.25),fw=plotX(7.3)-plotX(2.1),fh=plotY(0.25)-plotY(1.25);
    staticG.rect(fw,fh).move(fx0,fy0).fill('#fff').stroke({color:'#bbb',width:2});
    txt(staticG,4.7,0.75,'ΔMₖ ≈ f(x*ₖ, y*ₖ, z*ₖ) Δsₖ',Math.max(12,19*s),'middle');
    // red draggable sample point (persistent)
    redDot=draw.circle(Math.max(8,12*s)*2).fill(RED).stroke({color:'#fff',width:1.5}).css('cursor','pointer');
    redDot.on('mousedown',function(e){ dragging=true; if(e&&e.preventDefault)e.preventDefault(); });
    redDot.on('click',function(){ showPopup('Sample point P*ₖ','Drag this red point anywhere inside the subarc. The single term f(P*ₖ)·Δsₖ changes, but with a fine partition the total Riemann sum — and its limit, the line integral — stays essentially the same.'); });
    // readout titles (values appended dynamically)
    readG.text('').font({size:Math.max(12,18*s),family:'Georgia, serif'});
  }

  var dragging=false;
  document.addEventListener('mousemove',function(e){
    if(!dragging||!redDot) return;
    var rect=draw.node.getBoundingClientRect();
    var px=e.clientX-rect.left, py=e.clientY-rect.top;
    var wx=frame.xDomain[0]+(px-frame.margin)/frame.sx;
    var wy=frame.yDomain[0]+(frame.height-frame.margin-py)/frame.sy;
    var best=0,bd=1e9; for(var i=0;i<=60;i++){var p=insetPoint(i/60);var d=(p[0]-wx)*(p[0]-wx)+(p[1]-wy)*(p[1]-wy); if(d<bd){bd=d;best=i/60;}}
    u=best; updateDynamic();
  });
  document.addEventListener('mouseup',function(){ dragging=false; });

  function updateDynamic(){
    dynG.clear();
    var s=sc(), dr=Math.max(3.2,5*s), cw=Math.max(2.4,3.6*s);
    k=Math.max(1,Math.min(n,Math.round(n*0.62)));
    // partition dots + labels
    for(var i=0;i<=n;i++){
      var p=pointAtFrac(i/n);
      dynG.circle(dr*2).center(plotX(p[0]),plotY(p[1])).fill(BLUE);
      var lbl=null;
      if(i===1)lbl='P₁'; else if(i===2)lbl='P₂'; else if(i===3&&n>3)lbl='P₃'; else if(i===n-1&&n-1>3)lbl='Pₙ₋₁';
      if(lbl) txt(dynG,p[0]+0.18,p[1]-0.18,lbl,Math.max(12,18*s),'start');
    }
    // highlight kth subarc
    var hp=[]; for(var i=0;i<=30;i++){var p=pointAtFrac((k-1+i/30)/n);hp.push([plotX(p[0]),plotY(p[1])]);}
    dynG.polyline(hp.map(function(p){return p[0]+','+p[1];}).join(' ')).fill('none').stroke({color:'#ff8c1a',width:cw+3,linecap:'round',opacity:0.55});
    var mid=pointAtFrac((k-0.5)/n);
    // left Δs_k arrow over highlight
    var ay=mid[1]+0.7;
    dynG.line(plotX(mid[0]-0.45),plotY(mid[1]+0.15),plotX(mid[0]-0.45),plotY(ay+0.2)).stroke({color:'#222',width:1.3});
    dynG.line(plotX(mid[0]+0.45),plotY(mid[1]+0.15),plotX(mid[0]+0.45),plotY(ay+0.2)).stroke({color:'#222',width:1.3});
    darrow(dynG,plotX(mid[0]-0.45),plotY(ay),plotX(mid[0]+0.45),plotY(ay),'#222',1.5);
    txt(dynG,mid[0],ay+0.45,'Δsₖ',Math.max(12,18*s),'middle');
    // Mass ΔM_k label + curved arrow to highlight
    var ml=[1.1,4.4];
    txt(dynG,ml[0],ml[1],'Mass ΔMₖ',Math.max(12,18*s),'start');
    var ap=[ml[0]+1.5,ml[1]+0.25], cp=[mid[0]-0.6,mid[1]-0.6], tp=[mid[0]-0.1,mid[1]-0.15];
    var apath=[]; for(var i=0;i<=20;i++){var t=i/20,v=1-t;var x=v*v*ap[0]+2*v*t*cp[0]+t*t*tp[0],y=v*v*ap[1]+2*v*t*cp[1]+t*t*tp[1];apath.push([plotX(x),plotY(y)]);}
    dynG.polyline(apath.map(function(p){return p[0]+','+p[1];}).join(' ')).fill('none').stroke({color:'#222',width:1.3});
    var ta=Math.atan2(plotY(tp[1])-plotY(cp[1]),plotX(tp[0])-plotX(cp[0]));
    arrowHead(dynG,plotX(tp[0]),plotY(tp[1]),ta,6*s,'#222');
    // red dot position + label
    var rp=insetPoint(u);
    if(redDot) redDot.center(plotX(rp[0]),plotY(rp[1]));
    txt(dynG,rp[0]+0.05,rp[1]-0.5,'P*ₖ(x*ₖ, y*ₖ, z*ₖ)',Math.max(11,16*s),'middle');
    // readouts
    var rs=0; for(var i=0;i<n;i++){ rs+=dens(pointAtFrac((i+u)/n))*(L/n); }
    readG.clear();
    var fs=Math.max(12,18*s);
    halo(readG.text('Σ f(P*ₖ) Δsₖ  =  '+rs.toFixed(3)).move(plotX(8.0),plotY(9.5)).font({size:fs,family:'Georgia, serif'}).fill('#0a3d62'));
    halo(readG.text('∫_C f ds        =  '+EXACT.toFixed(3)).move(plotX(8.0),plotY(8.95)).font({size:fs,family:'Georgia, serif'}).fill('#117a3d'));
  }

  function render(){ buildStatic(); updateDynamic(); }

  document.addEventListener('fig-resize',function(){ render(); });

  // ---- controls ----
  window.update_partitionSegments=function(v){ n=Math.round(v); updateDynamic(); };

  // ---- demo steps ----
  var steps=[
    {t:'Coarse partition',narr:'With only a few segments, each arc’s mass is approximated by f at one sample point times Δsₖ; the Riemann sum Σ f(P*ₖ)Δsₖ is only a rough estimate of the true line integral shown beside it.',n:4},
    {t:'Refine the partition',narr:'Drag n upward: the blue sample points multiply along the curve, each Δsₖ shrinks, and the running sum visibly converges toward the exact value ∫_C f ds — this limit IS the line integral.',n:30},
    {t:'Move the sample point',narr:'With a fine partition, drag the red P*ₖ back and forth inside its subarc in the inset: the highlighted term f(P*ₖ)Δsₖ changes, but the total sum stays essentially fixed — the limit is independent of where you sample each arc.',n:30}
  ];
  var cur=0;
  function applyStep(i){
    cur=Math.max(0,Math.min(steps.length-1,i));
    var st=steps[cur];
    n=st.n;
    var sl=document.getElementById('partitionSegmentsInput'); if(sl){sl.value=n; var o=document.getElementById('partitionSegmentsVal'); if(o)o.value=n;}
    document.getElementById('demoNarration').textContent=st.narr;
    document.getElementById('stepLabel').textContent=(cur+1)+'/'+steps.length+' · '+st.t;
    updateDynamic();
  }
  window.prevStep=function(){ applyStep(cur-1); };
  window.nextStep=function(){ applyStep(cur+1); };

  render();
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

